/* Presentation of an authorized native KIDS profile. No receipt or score reader. */
(function(root){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),arr=v=>Array.isArray(v)?v:[];
 function project(input){
  const p=input.profile||{},practice=arr(input.practice),lessons=arr(p.assignments).filter(a=>a.kind==='lesson');
  const released=[...lessons,...practice],seen=new Set();
  const work=released.filter(a=>a.id&&!seen.has(a.id)&&seen.add(a.id));
  const reminders=arr(p.privateReminders||p.reminders||p.alerts);
  // Native reminders own inclusion. Native statusMeta owns every state label.
  const pending=reminders.map(r=>({reminder:r,item:work.find(a=>a.id===r.assignmentId)||null}));
  return {profile:p,lessons,practice,work,pending,upcoming:arr(input.upcoming)};
 }
 let input=null,state=null,host=null,nativeBanner=null,tab='plan',category=null,openId=null;
 function disable(){if(nativeBanner&&host?.contains(nativeBanner)){const shell=root.document.getElementById('dashboardShell');shell.insertBefore(nativeBanner,shell.querySelector('.tabs'));}root.document?.body.classList.remove('kids-program-pilot-active');host?.remove();host=null;input=null;state=null;}
 const idFor=a=>String(a.id||a.lessonKey||'');
 function context(a){return [a.program,a.kind==='lesson'?'Tiết '+a.sessionNumber:'Tự luyện',a.dueDate?'Hạn '+a.dueDate:''].filter(Boolean).join(' · ');}
 function nativeHTML(a){return a.kind==='lesson'?input.lessonHTML(a):input.practiceHTML(a);}
 function rows(items){return items.map(a=>{const status=input.status(a);return '<button type="button" class="kp-task-row" data-kp-detail="'+esc(idFor(a))+'" aria-haspopup="dialog"><span><strong>'+esc(a.title||a.topic||a.session)+'</strong><small>'+esc(context(a))+'</small></span><span class="kp-task-state '+esc(status.cls)+'">'+esc(status.label||'Xem chi tiết')+'</span><span class="kp-arrow" aria-hidden="true">↗</span></button>';}).join('');}
 function modal(title,context,html){const d=host.querySelector('#kp-detail');d.querySelector('.kp-modal-context').textContent=context;d.querySelector('h2').textContent=title;d.querySelector('.kp-native-detail').innerHTML=html;if(!d.open)d.showModal();}
 function openDetail(id){const a=state.work.find(x=>idFor(x)===id);if(!a)return;openId=id;modal(a.title||a.session||'Chi tiết bài học',context(a),nativeHTML(a));}
 function listPending(overdue){openId=overdue?'@overdue':'@pending';const pending=state.pending.filter(x=>x.item&&(input.status(x.item).cls==='late')===overdue).map(x=>x.item);modal(overdue?'Bài làm bù quá hạn':'Bài cần hoàn thành',input.className,rows(pending)||'<p class="kp-empty">Con hiện không có bài '+(overdue?'quá hạn cần làm bù.':'trong danh sách này.')+'</p>');}
 function planHTML(){
  const late=state.pending.filter(x=>x.item&&input.status(x.item).cls==='late'),due=state.pending.filter(x=>!late.includes(x)),books=[...new Set(state.upcoming.map(s=>s.program))],next=books.map(b=>state.upcoming.find(s=>s.program===b));
  return '<div class="kp-grid"><div><section class="kp-panel kp-todo"><header class="kp-section-head"><div><small>HỌC ĐỀU MỖI NGÀY</small><h2>Việc cần làm tuần này</h2></div><span class="kp-count">'+state.pending.length+' bài</span></header>'+
   (due.length?due.map(x=>x.item?'<div class="kp-work-type">'+esc(x.item.kind==='self-practice'?'🎬 Tự luyện · '+x.item.program:'💻 Bài tập trên lớp · '+x.item.program)+'</div>'+rows([x.item]):'<p>'+esc(x.reminder.title)+'</p>').join(''):'<p class="kp-empty">Chưa có bài mới cần hoàn thành.</p>')+
   '<button class="kp-overdue" data-kp-overdue aria-haspopup="dialog"><span>'+esc(input.alias)+' · <strong>'+late.length+' bài</strong> quá hạn cần làm bù</span><span>Xem ↗</span></button></section>'+
   '<section class="kp-panel"><small class="kp-eyebrow">NHẬT KÝ BUỔI HỌC</small><h2>Những buổi học gần đây</h2>'+(state.lessons.length?rows(state.lessons.slice(0,4)):'<p class="kp-empty">Con mới nhập học từ '+esc(state.profile.joinDate)+'. Chưa có buổi học đã hoàn thành trong khoảng này.</p>')+'</section></div><aside><section class="kp-panel"><small class="kp-eyebrow">LỊCH RIÊNG THEO TỪNG SÁCH</small><h2>Buổi học kế tiếp</h2>'+next.map(s=>'<article class="kp-next"><span>'+esc(s.program)+'</span><h3>Tiết '+s.sessionNumber+' · '+esc(s.date)+'</h3><p>'+esc(s.topic)+'</p><b>'+esc(s.startTime)+' – '+esc(s.endTime)+'</b></article>').join('')+'</section><section class="kp-panel kp-join"><h3>🌱 Hành trình mới bắt đầu</h3><p>Ngày nhập học: <strong>'+esc(state.profile.joinDate)+'</strong></p><p>Hồ sơ dùng bài đã được phát hành từ ngày nhập học. Lịch tương lai không tính là bài thiếu.</p></section></aside></div>';
 }
 function libraryHTML(){const books=[...new Set(state.work.map(x=>x.program))];if(!category||!books.includes(category))category=books[0];return '<section class="kp-panel"><small class="kp-eyebrow">KHO BÀI TẬP</small><h2>Bài tập & Video</h2><div class="kp-book-tabs">'+books.map(b=>'<button data-kp-book="'+esc(b)+'" '+(b===category?'aria-current="page"':'')+'>'+esc(b)+'</button>').join('')+'</div>'+rows(state.work.filter(a=>a.program===category))+(books.length?'':'<p class="kp-empty">Chưa có bài học được phát hành cho hồ sơ này.</p>')+'</section>';}
 function draw(){
  const before=host.querySelector('#kp-detail'),wasOpen=before?.open,scroll=before?.scrollTop||0;nativeBanner?.remove();
  host.innerHTML='<header class="kp-hero"><div><small>MS. TRANG TRIEU EDUCATION</small><h1>'+esc(input.alias)+' <span>· '+esc(input.className)+'</span></h1><p>'+esc(input.label||input.alias)+'</p><span class="kp-join-date">Từ ngày nhập học '+esc(state.profile.joinDate)+'</span></div><div class="kp-kpis"><div><b>'+esc(state.profile.summary?.totalStars??'—')+'</b><span>Sao tích lũy</span></div><div><b>'+state.pending.length+'</b><span>Bài cần hoàn thành</span></div></div></header>'+
   '<nav class="kp-tabs" aria-label="Hồ sơ học tập">'+[['plan','📅 Kế hoạch & Lịch học'],['library','🎬 Bài tập & Video'],['results','🏆 Kết quả & Xếp hạng']].map(([id,label])=>'<button data-kp-tab="'+id+'" '+(tab===id?'aria-current="page"':'')+'>'+label+'</button>').join('')+'</nav><div class="kp-content">'+(tab==='plan'?planHTML():tab==='library'?libraryHTML():'<div class="kp-native-results">'+input.resultsHTML+'<div class="kp-native-competition">'+input.competitionHTML+'</div></div>')+'</div>'+
   '<dialog id="kp-detail" aria-labelledby="kp-modal-title"><header class="kp-modal-head"><div><small class="kp-modal-context"></small><h2 id="kp-modal-title"></h2></div><button type="button" data-kp-close aria-label="Đóng chi tiết">×</button></header><div class="kp-native-detail"></div><footer><button type="button" data-kp-close>Đóng · Quay lại</button></footer></dialog>';
  if(nativeBanner)host.querySelector('.kp-content').prepend(nativeBanner);
  if(wasOpen&&openId){if(openId.startsWith('@'))listPending(openId==='@overdue');else openDetail(openId);host.querySelector('#kp-detail').scrollTop=scroll;}
 }
 function update(value){
  if(!value?.authorized||value.revoked||value.classNumber!==8||value.alias!=='TEST K8'||value.profile?.englishName!==value.alias||value.parentHash!==root.location.hash){disable();return false;}
  input=value;state=project(value);nativeBanner=root.document.getElementById('pendingWorkBanner');
  if(!host){host=root.document.createElement('section');host.id='kids-program-pilot';root.document.getElementById('dashboardShell').prepend(host);host.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.id==='pendingWorkOpen')listPending(false);else if(b.dataset.kpTab){tab=b.dataset.kpTab;openId=null;draw();}else if(b.dataset.kpBook){category=b.dataset.kpBook;draw();}else if(b.dataset.kpDetail)openDetail(b.dataset.kpDetail);else if(b.hasAttribute('data-kp-overdue'))listPending(true);else if(b.hasAttribute('data-kp-close')){host.querySelector('#kp-detail').close();openId=null;}});}
  root.document.body.classList.add('kids-program-pilot-active');draw();return true;
 }
 root.KidsProgramPilot={project,update,disable};root.addEventListener?.('hashchange',disable);root.document?.addEventListener('click',event=>{if(host&&event.target.closest('#pendingWorkGateOpen'))listPending(false);});root.dispatchEvent?.(new Event('kids-program-pilot-ready'));
 if(typeof module==='object'&&module.exports)module.exports={project};
})(typeof window!=='undefined'?window:globalThis);
